(event: MouseEvent) => {
    // Prevent the click event from being emitted when the button is disabled
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
    } else {
      this.emit('sc-action', {
        detail: {
          target: event.target,
          data: {
            href: this.href,
            target: this.target,
            value: this.value,
            checked: this.checked,
          },
        },
      });
      if (this.href && !this.preventDefaultLink) {
        window.open(this.href, this.target || '_self');
      }
    }
  }

(event: KeyboardEvent) => {
    switch (event.key) {
      case 'Escape':
      case 'Tab':
        this.disableSubmenu();
        break;
      case 'ArrowLeft':
        // Either focus is currently on the host element or a child
        if (event.target !== this.host) {
          event.preventDefault();
          event.stopPropagation();
          this.host.focus();
          this.disableSubmenu();
        }
        break;
      case 'ArrowRight':
      case 'Enter':
      case ' ':
        this.handleSubmenuEntry(event);
        break;
      default:
        break;
    }
  }

(event: MouseEvent) => {
    // Clicking on the item which heads the menu does nothing, otherwise hide submenu and propagate
    if (event.target === this.host) {
      event.preventDefault();
      event.stopPropagation();
    } else if (
      event.target instanceof Element &&
      (event.target.tagName === 'sl-menu-item' || event.target.role?.startsWith('menuitem'))
    ) {
      this.disableSubmenu();
    }
  }

(event: FocusEvent) => {
    if (event.relatedTarget && event.relatedTarget instanceof Element && this.host.contains(event.relatedTarget)) {
      return;
    }
    this.disableSubmenu();
  }

() => {
    const submenuSlot: HTMLSlotElement | null = this.host.renderRoot.querySelector('slot[name=\'submenu\']');
    const menu = submenuSlot?.assignedElements({ flatten: true }).filter(el => el.localName === 'sl-menu')[0];
    const isRtl = getComputedStyle(this.host).direction === 'rtl';
    if (!menu) {
      return;
    }

    const { left, top, width, height } = menu.getBoundingClientRect();

    this.host.style.setProperty('--safe-triangle-submenu-start-x', `${isRtl ? left + width : left}px`);
    this.host.style.setProperty('--safe-triangle-submenu-start-y', `${top}px`);
    this.host.style.setProperty('--safe-triangle-submenu-end-x', `${isRtl ? left + width : left}px`);
    this.host.style.setProperty('--safe-triangle-submenu-end-y', `${top + height}px`);
  }

(e: KeyboardEvent) => {
    const activeEl = this.shadowRoot?.activeElement;
    if (activeEl?.tagName === 'INPUT') return;

    switch (e.key) {
      case 'ArrowLeft':
        e.preventDefault();
        this.goPrev();
        break;
      case 'ArrowRight':
        e.preventDefault();
        this.goNext();
        break;
      case 'Home':
        e.preventDefault();
        this.goFirst();
        break;
      case 'End':
        e.preventDefault();
        this.goLast();
        break;
      case 'PageUp':
        e.preventDefault();
        this.jumpBackward();
        break;
      case 'PageDown':
        e.preventDefault();
        this.jumpForward();
        break;
      case 'Enter':
      case ' ':
        const target = e.composedPath()[0] as HTMLElement;
        if (
          target?.classList.contains('sc-pagination-item') ||
          target?.classList.contains('sc-pagination-jump-prev') ||
          target?.classList.contains('sc-pagination-jump-next')
        ) {
          e.preventDefault();
          target.click();
        }
        break;
    }
  }

() => {
    this.emit('sc-change', {
      detail: this.changeObject,
      bubbles: true,
      composed: true,
    });
