      _valueAsDate = {
        start: dayjs(correctPartDate(value.start || this.value.start)),
        end: dayjs(correctPartDate(value.end || this.value.end)),
      };
    } else if (value) {
      const valueDate = getDate(value);
      this._valueAsDate = valueDate;
      this.value = getDateString(valueDate);
      this._valueString = getDateString(valueDate);
      _valueAsDate = dayjs(correctPartDate(value));
