    event.stopPropagation();

    if (this._disabled || this.readonly) return;
    const target = event.target as HTMLInputElement | null;
    const inputValue = target?.value ?? '';

    this._hasInputDraft = true;
    this._inputDraft = inputValue;

    if (!inputValue) return;

    // Only proceed when the input length matches the format length.
    if (inputValue.length !== (this.format as string).length) return;

    // Parse strictly against the configured format; treat any mismatch as invalid.
    const parsedByFormat = dayjs(inputValue, this.format as string, true);
    if (!parsedByFormat.isValid()) return;

    const normalizedInput = parsedByFormat.format(this.format as string);
    if (normalizedInput !== inputValue) return;

    if (this.range && (this.displayValue === 'start' || this.displayValue === 'end')) {
      const currentRangeValue =
        this.value && typeof this.value === 'object' ? this.value : { start: '', end: '' };
      this.updateValues(
        { ...currentRangeValue, [this.displayValue]: normalizedInput },
        true,
        true
      );
      return;
    }

    this.updateValues(normalizedInput, true, true);
  }

