{
  getDefaultOptions: <TData extends RowData>(
    table: Table<TData>
  ): GroupingTreeOptions => {
    return {
      onGroupingTreeColumnIdChange: makeStateUpdater(
        'groupingTreeColumnId',
        table
      ),
    } as GroupingTreeOptions;
  },
  createTable: <TData extends RowData>(table: Table<TData>): void => {
    table.getGroupTreeColumnId = () => table.getState().groupingTreeColumnId;
    table.setGroupTreeColumnId = updater =>
      table.options.onGroupingTreeColumnIdChange(updater);

    table.getIsGroupTree = memo(
      () => [table.getState().grouping, table.getGroupTreeColumnId()],
      (grouping, columnId) =>
        !!columnId && grouping.includes(columnId)
    );
  },
  createColumn: <TData extends RowData>(
    column: Column<TData>,
    table: Table<TData>
  ): void => {
    column.getIsGroupTreeColumn = memo(
      () => [table.getState().groupingTreeColumnId, column.id],
      (groupingTreeColumnId, columnId) =>
        groupingTreeColumnId === columnId
    );
  },
  createRow: <TData extends RowData>(
    row: Row<TData>,
    table: Table<TData>,
  ): void => {
    row.getGroupTreeFullPath = () => {
      const columnId = table.getGroupTreeColumnId();
      if (columnId) {
        const column = table.getColumn(columnId);
        if (column) {
          const getPath = column.columnDef.meta?.getGroupingTreePath;
          if (getPath) return getPath(row.original, row.index);
          if (!column?.accessorFn) return undefined;

          const value = column.accessorFn(row.original, row.index);
          const path = Array.isArray(value) ? value : [value];
          return path.map(v => `${v}`);
        }
      }
    };
    row.getGroupTreePath = () => row.getGroupTreeFullPath()?.slice(0, -1);
    row.getGroupTreeLeaf = () => row.getGroupTreeFullPath()?.slice(-1)[0];
    row.getIsGroupTreeLeaf = () =>
      row.depth + 1 === row.getGroupTreeFullPath()?.length;

    row.getValue = (columnId: string) => {
      if (!row._valuesCache.hasOwnProperty(columnId)) {
        if (columnId === table.getGroupTreeColumnId()) {
          row._valuesCache[columnId] = row.getGroupTreeLeaf();
        } else {
          // original implementation of getValue
          const column = table.getColumn(columnId);
          if (!column?.accessorFn) return undefined;
          row._valuesCache[columnId] = column.accessorFn(
            row.original as TData,
            row.index
          );
        }
      }
      return row._valuesCache[columnId] as any;
    };
  },
  createCell: <TData extends RowData, TValue>(
    cell: Cell<TData, TValue>,
    column: Column<TData>,
  ): void => {
    const _getIsPlaceholder = cell.getIsPlaceholder;
    cell.getIsPlaceholder = () =>
      _getIsPlaceholder() && !column.getIsGroupTreeColumn();
    cell.getIsGroupingTreeColumn = () => column.getIsGroupTreeColumn();
  },
}

{
  getInitialState: (state): RowDraggableTableState => {
    return {
      orderedRowIdViaDragging: [],
      orderedDraggableRows: [],
      ...state,
    };
  },

  getDefaultOptions: <TData extends RowData>(
    table: Table<TData>
  ): RowDraggableOptions => {
    return {
      onOrderedRowIdViaDraggingChange: makeStateUpdater(
        'orderedRowIdViaDragging',
        table
      ),
      onOrderedDraggableRowsChange: makeStateUpdater(
        'orderedDraggableRows',
        table
      ),
    } as RowDraggableOptions;
  },
  createTable: <TData extends RowData>(table: Table<TData>): void => {
    table.setOrderedRowIdViaDragging = updater =>
      table.options.onOrderedRowIdViaDraggingChange?.(updater);
    table.setOrderedDraggableRows = updater =>
      table.options.onOrderedDraggableRowsChange?.(updater);

    table.getIsEnableDraggableRow = memo(
      () => [table.getState(), table.options],
      (tableState, tableOptions) => {
        // also will ignore pinned top/bottom rows
        const sorted = tableState.sorting.length > 0;
        const filtered = tableState.columnFilters.length > 0;
        const globalSorted = tableState.globalFilter;
        const grouped = tableState.grouping.length > 0;
        const isEnablePagination = tableOptions.isEnablePagination;
        const isManual = tableOptions.manualFiltering || tableOptions.manualSorting;
        if (
          isManual ||
          isEnablePagination ||
          sorted ||
          filtered ||
          globalSorted ||
          grouped
        ) {
          return false;
        }

        return Boolean(tableOptions.enableDraggableRow);
      }
    );
  },
  createColumn: <TData extends RowData, TValue>(
    column: Column<TData, TValue>,
    table: Table<TData>
  ): void => {
    column.getIsDraggable = () => {
      if (!table.options.enableDraggableRow) {
        return false;
      }
      return column.columnDef.meta?.draggable ?? false;
    };
  },
  createCell: <TData extends RowData, TValue>(
    cell: Cell<TData, TValue>,
    column: Column<TData, TValue>,
    row: Row<TData>,
    table: Table<TData>
  ): void => {},
  createRow: <TData extends RowData>(
    row: Row<TData>,
    table: Table<TData>
  ): void => {
    row.getIsDraggable = memo(
      () => [
        table.getState().rowPinning.top,
        table.getState().rowPinning.bottom,
      ],
      (top, bottom) => {
        const pinnedRowIds = new Set([...(top ?? []), ...(bottom ?? [])]);
        return !pinnedRowIds.has(row.id);
      }
    );
  },
}

